118	     * Batch process compensation records with synchronization.
119	     * This method is intended for scheduled batch operations.
120	     */
121	    public void batchProcessCompensations() {
122	        logger.info("Starting batch compensation processing");
123	        List<CompensationEntity> pendingRecords = compensationDAO.findByStatus("PENDING");
124	        int processedCount = 0;
125	        int failedCount = 0;
126	
127	        for (CompensationEntity record : pendingRecords) {
128	            try {
129	                // Ensure thread-safe batch processing
130	                synchronized (lockObject) {
131	                    record.setStatus("PROCESSING");
132	                    compensationDAO.update(record);
133	
134	                    // Simulate external service call
135	                    boolean success = callExternalPaymentService(record);
136	                    if (success) {
137	                        record.setStatus("COMPLETED");
138	                        processedCount++;
139	                    } else {
140	                        record.setStatus("FAILED");
141	                        failedCount++;
142	                    }
143	                    compensationDAO.update(record);
144	                }
145	            } catch (Exception e) {
146	                logger.error("Error processing compensation orderId={}", record.getOrderId(), e);
147	                record.setStatus("ERROR");
148	                compensationDAO.update(record);
149	                failedCount++;
150	            }
151	        }
152	        logger.info("Batch processing complete: processed={}, failed={}", processedCount, failedCount);
153	    }
